#!/bin/sh
# Test stub standing in for the whisper.cpp CLI (whisper-cli): writes
# the canned -ojf JSON for the JFK fixture to <output-base>.json and
# prints the segment line, ignoring the audio entirely. Used by
# test/mcp-test.mjs so the whisper.cpp engine path (binary discovery,
# JSON parsing, .srt writing, word timestamps from tokens) is exercised
# without a real binary or model — the real engine is covered by the
# MEDIAKIT_TEST_WHISPER_CPP gated block instead. The tokens below are
# the real token list from whisper-cli b5454 + ggml-tiny on the JFK
# fixture (measured 2026-11-13), not invented: " fellow" 950-1590ms,
# " Americans" 1590-2100ms, and the first token " And" reports
# from == to (320ms), which the word grouping floors to 0.1s.
out=""
prev=""
for a in "$@"; do
  if [ "$prev" = "-of" ]; then out="$a"; fi
  prev="$a"
done
if [ -z "$out" ]; then echo "stub: no -of given" >&2; exit 2; fi
cat > "$out.json" <<'JSON'
